// Read-only fullCartesian finite sphere expansion quadrature; no radial average.
#include <fstream>
#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/composite_checkpoint.hpp"
#include "mesh/cubed_sphere/composite_difference.hpp"
#include "z4c/hyperboloidal/composite_state.hpp"
#include "z4c/hyperboloidal/surface_mass.hpp"
namespace c=cubed_sphere;namespace h=z4c::hyperboloidal;using V=std::vector<Real>;
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=8&&argc!=10)throw std::runtime_error("snapshot tag initial.dat quadrature.dat initial-oracle.dat mode output.csv");const auto snap=c::CompositeCheckpoint::Read(argv[1],argv[2]);if(snap.mesh.cells!=10||snap.step!=2||snap.positive_storage!=2||!snap.wormhole_chart||snap.isotropic_reference)throw std::runtime_error("expected actualfinalN10acceptedMinkreference logchart");c::CompositeDifference grid(snap.mesh,snap.spatial_order,snap.radial_interface_stencils);if(grid.active.size()>50000)throw std::runtime_error("bounded50000");const std::string mode=argv[6];if(mode!="final"&&mode!="initial"&&mode!="mink"&&mode!="analytic_initial")throw std::runtime_error("unknown mass mode");V field(22*grid.count,0);
 if(mode=="final")for(size_t p=0;p<grid.active.size();++p)for(int f=0;f<22;++f)field[f*grid.count+grid.active[p]]=snap.fields[22*p+f];
 if(mode=="initial"){std::ifstream in(argv[3]);std::string magic;size_t count;in>>magic>>count;if(magic!="ISOTROPIC_M1_3"||count!=grid.active.size())throw std::runtime_error("initial layout");for(size_t p=0;p<count;++p){Real r,chi,alpha,Arr,Khat;in>>r>>chi>>alpha>>Arr>>Khat;const auto&x=grid.geometry[p].x;Real radius=0;for(Real v:x)radius+=v*v;radius=std::sqrt(radius);if(!in||std::abs(radius-r)>1e-13||!(chi>0&&alpha>0))throw std::runtime_error("initial point provenance/positivity");const int id=grid.active[p];field[id]=std::log(chi);field[18*grid.count+id]=std::log(alpha/((1+r*r)/2));field[13*grid.count+id]=Khat+3;for(int t=0;t<6;++t){const int i=h::kCompositeTensorI[t],j=h::kCompositeTensorJ[t];field[(7+t)*grid.count+id]=1.5*Arr*(x[i]*x[j]/(r*r)-(i==j?1./3:0));}}}
 struct Point{int i,j;Real mu,phi,n[3],weight;};std::ifstream qin(argv[4]);std::string magic;int nmu,nphi;qin>>magic>>nmu>>nphi;if(magic!="GLPHI"||nmu*nphi>2048||nmu*nphi<128)throw std::runtime_error("bounded angular quadrature");std::vector<Point>points(nmu*nphi);for(auto&p:points)qin>>p.i>>p.j>>p.mu>>p.phi>>p.n[0]>>p.n[1]>>p.n[2]>>p.weight;if(!qin)throw std::runtime_error("quadrature data");std::ifstream orin(argv[5]);std::getline(orin,magic);Real oracle[8][6];for(auto &row:oracle)for(Real&v:row)orin>>v;if(!orin)throw std::runtime_error("initial oracle data");const Real radii[8]={.05,.1,.2,.3,.5,.7,.85,.95};
 std::ofstream out(argv[7]);out<<std::setprecision(17)<<"radius,mu_index,phi_index,mu,phi,x,y,z,solid_weight,owner,face,layer,valid,alpha,chi,metric_det,area_per_solid_angle,mean_curvature,curvature_trace,theta_plus,theta_minus,expansion_product\n";std::cout<<std::setprecision(17)<<"{\"mode\":\""<<mode<<"\",\"n_mu\":"<<nmu<<",\"n_phi\":"<<nphi<<",\"angular_points\":"<<points.size()<<",\"time\":"<<(mode=="final"?snap.step*snap.dt:0)<<",\"surfaces\":[";Real max_exact_error=0;
 const int sphere_begin=argc==10?std::stoi(argv[8]):0,sphere_end=argc==10?std::stoi(argv[9]):8;if(sphere_begin<0||sphere_end>8||sphere_begin>=sphere_end)throw std::runtime_error("sphere range guard");for(int sphere=sphere_begin;sphere<sphere_end;++sphere){if(sphere>sphere_begin)std::cout<<',';const Real radius=radii[sphere];long double area=0,product=0,solid=0;size_t failures=0;Real minarea=1e300,maxarea=0,minproduct=1e300,maxproduct=-1e300;for(const auto&p:points){Real x[3];for(int i=0;i<3;++i)x[i]=radius*p.n[i];const int owner=grid.mesh.Owner(x);h::Z4cJet<Real>u{};h::SphereExpansion<Real>local{};Real determinant=0;bool valid=false;try{if(mode=="analytic_initial"){for(int i=0;i<3;++i){u.metric.g[i][i]=1;u.chi.d[i]=oracle[sphere][2]*p.n[i];}u.chi.value=oracle[sphere][1];u.alpha.value=oracle[sphere][5];u.trace.value=oracle[sphere][4];for(int i=0;i<3;++i)for(int j=0;j<3;++j)u.a.k[i][j]=1.5*oracle[sphere][3]*(p.n[i]*p.n[j]-(i==j?1./3:0));}else{V values;std::vector<std::array<Real,3>>d;std::vector<std::array<std::array<Real,3>,3>>dd;grid.SampleJets(field,22,x,values,d,dd);u=h::UnpackComposite(x,values,d,dd,true,0,2);}h::OmegaJet<Real>o{};o.omega=(1-radius*radius)/2;for(int i=0;i<3;++i)o.gradient[i]=-x[i];local=h::CoordinateSphereExpansion(u,o,x);valid=local.valid;determinant=h::Geometry(u.metric).determinant;}catch(const std::exception&e){std::cerr<<mode<<" radius="<<radius<<" mu="<<p.i<<" phi="<<p.j<<" reason="<<e.what()<<'\n';}if(!valid)++failures;solid+=p.weight;if(valid){area+=(long double)p.weight*local.area_per_solid_angle;product+=(long double)p.weight*local.area_per_solid_angle*local.product;minarea=std::min(minarea,local.area_per_solid_angle);maxarea=std::max(maxarea,local.area_per_solid_angle);minproduct=std::min(minproduct,local.product);maxproduct=std::max(maxproduct,local.product);}out<<radius<<','<<p.i<<','<<p.j<<','<<p.mu<<','<<p.phi<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<p.weight<<','<<owner<<','<<(owner<0?-99:grid.mesh.blocks[owner].face)<<','<<(owner<0?-99:grid.mesh.blocks[owner].layer)<<','<<valid<<','<<u.alpha.value<<','<<u.chi.value<<','<<determinant<<','<<local.area_per_solid_angle<<','<<local.mean_curvature<<','<<local.curvature_trace<<','<<local.theta_plus<<','<<local.theta_minus<<','<<local.product<<'\n';}
 const auto mass=h::HawkingSurfaceMass(Real(area),Real(product));const long double pi=std::acos((long double)-1),R=std::sqrt(area/(4*pi)),mass_ld=R/2*(1+product/(16*pi));std::cout<<"{\"radius\":"<<radius<<",\"samples\":"<<points.size()<<",\"failed_samples\":"<<failures<<",\"valid\":"<<(!failures&&mass.valid)<<",\"solid_weight_sum\":"<<Real(solid)<<",\"area\":"<<Real(area)<<",\"integrated_expansion_product\":"<<Real(product)<<",\"areal_radius\":"<<mass.areal_radius<<",\"mass\":"<<mass.mass<<",\"mass_extended_summation\":"<<Real(mass_ld)<<",\"area_density_min\":"<<minarea<<",\"area_density_max\":"<<maxarea<<",\"product_min\":"<<minproduct<<",\"product_max\":"<<maxproduct<<'}';if(failures||!mass.valid)code=2;if(mode=="mink"||mode=="analytic_initial")max_exact_error=std::max(max_exact_error,std::abs(mass.mass-(mode=="mink"?0.:1./3)));}
 std::cout<<"],\"max_exact_control_error\":"<<max_exact_error<<",\"no_evolution_or_solve\":true,\"finite_surfaces_only\":true}\n";if((mode=="mink"||mode=="analytic_initial")&&max_exact_error>1e-9)code=3;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
